// ⭐ CHANGE THESE
const profile = {
  avatar: "👋",
  tagline: "A tiny website about big favorites, bright ideas, and things I love making."
};
const facts = [
  { emoji: "🧩", title: "I like solving puzzles", text: "The best part is finding the trick." },
  { emoji: "🎮", title: "I build playful things", text: "Games, pages, stories, and experiments." },
  { emoji: "🌈", title: "Favorite color mood", text: "Anything bright enough to feel cheerful." }
];
const favorites = [
  { emoji: "🍕", title: "Snack", text: "Pizza" },
  { emoji: "🐬", title: "Animal", text: "Dolphin" },
  { emoji: "🚀", title: "Dream trip", text: "Space" }
];

const avatar = document.getElementById("avatar");
const tagline = document.getElementById("tagline");
const factsEl = document.getElementById("facts");
const favoritesEl = document.getElementById("favorites");

avatar.textContent = profile.avatar;
tagline.textContent = profile.tagline;
factsEl.innerHTML = facts.map((fact) => `
  <article>
    <span>${fact.emoji}</span>
    <h3>${fact.title}</h3>
    <p>${fact.text}</p>
  </article>
`).join("");
favoritesEl.innerHTML = favorites.map((item) => `
  <div class="favorite">
    <span>${item.emoji}</span>
    <h3>${item.title}</h3>
    <p>${item.text}</p>
  </div>
`).join("");

avatar.addEventListener("click", () => {
  avatar.classList.remove("wave");
  void avatar.offsetWidth;
  avatar.classList.add("wave");
});

* { box-sizing: border-box; }
/* jr-theme-tokens-v1 */
:root {
  --jr-bg: #f8fafc;
  --jr-surface: #ffffff;
  --jr-text: #172033;
  --jr-accent: #0f766e;
  --jr-accent-contrast: #ffffff;
}
body {
  margin: 0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--jr-bg);
  color: var(--jr-text);
}
.hero {
  min-height: 46vh;
  display: grid;
  grid-template-columns: 150px minmax(0, 780px);
  align-items: center;
  justify-content: center;
  gap: 30px;
  padding: 52px 24px;
  background: linear-gradient(135deg, var(--jr-bg), var(--jr-surface) 48%, var(--jr-accent));
}
.avatar {
  width: 140px;
  height: 140px;
  border: 0;
  border-radius: 50%;
  background: var(--jr-accent);
  color: var(--jr-accent-contrast);
  font-size: 76px;
  box-shadow: 0 22px 60px rgba(15, 23, 42, 0.18);
  animation: bob 2.2s ease-in-out infinite;
}
.avatar.wave { animation: wave 0.7s ease, bob 2.2s ease-in-out infinite 0.7s; }
p {
  margin: 0 0 10px;
  color: var(--jr-accent);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
h1 { max-width: 820px; margin: 0; font-size: clamp(46px, 9vw, 92px); line-height: 0.9; }
strong { display: block; margin-top: 18px; color: var(--jr-text); opacity: 0.78; font-size: 22px; line-height: 1.45; }
main {
  width: min(1060px, calc(100vw - 40px));
  margin: 0 auto;
  padding: 34px 0 54px;
  display: grid;
  gap: 34px;
}
h2 { margin: 0 0 14px; font-size: 28px; }
.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
article,
.favorite {
  border: 1px solid #d7deea;
  border-radius: 8px;
  background: var(--jr-surface);
  padding: 18px;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.06);
}
article span,
.favorite span { display: block; font-size: 34px; }
article h3,
.favorite h3 { margin: 8px 0 5px; }
article p,
.favorite p { margin: 0; color: #64748b; text-transform: none; letter-spacing: 0; font-weight: 700; }
.favorites { display: flex; gap: 12px; flex-wrap: wrap; }
.favorite { flex: 1 1 180px; }
@keyframes bob { 50% { transform: translateY(-9px); } }
@keyframes wave { 35% { transform: rotate(14deg) scale(1.06); } 70% { transform: rotate(-10deg) scale(1.04); } }
@media (max-width: 720px) {
  .hero { grid-template-columns: 1fr; text-align: center; justify-items: center; }
  .grid { grid-template-columns: 1fr; }
}

// ⭐ CHANGE THESE
const floatingThings = [
  { emoji: "✨", x: 140, y: 150, size: 54, color: "#facc15", speed: 0.018 },
  { emoji: "💡", x: 350, y: 250, size: 64, color: "#38bdf8", speed: -0.014 },
  { emoji: "🎨", x: 610, y: 165, size: 58, color: "#fb7185", speed: 0.022 }
];

const canvas = document.getElementById("stage");
const ctx = canvas.getContext("2d");
const themeColors = {
  background: readThemeToken("--jr-bg"),
  surface: readThemeToken("--jr-surface"),
  text: readThemeToken("--jr-text")
};
let tick = 0;

function draw() {
  tick += 1;
  const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
  gradient.addColorStop(0, tick % 180 < 90 ? themeColors.surface : themeColors.background);
  gradient.addColorStop(1, themeColors.background);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = themeColors.text;
  ctx.globalAlpha = 0.55;
  for (let i = 0; i < 48; i++) {
    ctx.fillRect((i * 83 + tick * 0.7) % canvas.width, (i * 47) % canvas.height, 3, 3);
  }
  ctx.globalAlpha = 1;

  ctx.textAlign = "center";
  for (const item of floatingThings) {
    const y = item.y + Math.sin(tick * item.speed) * 28;
    ctx.font = `${item.size}px system-ui`;
    ctx.fillText(item.emoji, item.x, y);
    ctx.fillStyle = item.color;
    ctx.beginPath();
    ctx.arc(item.x, y + 20, item.size * 0.28, 0, Math.PI * 2);
    ctx.globalAlpha = 0.22;
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  ctx.fillStyle = themeColors.text;
  ctx.font = "bold 30px system-ui";
  ctx.fillText("Ask Jr. to shape this idea.", canvas.width / 2, 438);
  requestAnimationFrame(draw);
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

draw();

* { box-sizing: border-box; }
/* jr-theme-tokens-v1 */
:root {
  --jr-bg: #172033;
  --jr-surface: #020617;
  --jr-text: #f8fafc;
  --jr-accent: #67e8f9;
  --jr-accent-contrast: #e0f2fe;
}
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #172033;
  color: #f8fafc;
}
.shell {
  width: min(94vw, 920px);
}
header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}
p {
  margin: 0;
  color: #7dd3fc;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
h1 {
  margin: 0;
  text-align: right;
  font-size: clamp(30px, 6vw, 56px);
  line-height: 1;
}
canvas {
  width: 100%;
  display: block;
  aspect-ratio: 41 / 26;
  border: 4px solid #67e8f9;
  border-radius: 8px;
  background: #020617;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.38);
}
body { background: var(--jr-bg); color: var(--jr-text); }
p, h1 { color: var(--jr-accent-contrast); }
canvas { border-color: var(--jr-accent); background: var(--jr-surface); }

// ⭐ CHANGE THESE
const brickEmoji = "🧱";
const ballEmoji = "⚽";
const brickColors = ["#f97316", "#facc15", "#4ade80", "#38bdf8", "#a78bfa"];
const powerups = [
  { emoji: "🍭", type: "wide", weight: 5 },
  { emoji: "⏳", type: "slow", weight: 4 },
  { emoji: "❤️", type: "life", weight: 1 }
];
const levels = [
  [
    "111111",
    "011110",
    "001100"
  ],
  [
    "121121",
    "011110",
    "111111"
  ],
  [
    "212212",
    "121121",
    "011110"
  ],
  [
    "222222",
    "121121",
    "212212"
  ]
];

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const status = document.getElementById("status");
const themeColors = {
  background: readThemeToken("--jr-bg"),
  surface: readThemeToken("--jr-surface"),
  accent: readThemeToken("--jr-accent"),
  text: readThemeToken("--jr-text")
};
const keys = new Set();
const paddle = { x: 360, y: 500, w: 150, h: 18, speed: 9 };
const ball = { x: 450, y: 430, vx: 4.2, vy: -5.4, r: 15 };
const stars = makeStars(70);
const particles = [];
const trail = [];
const drops = [];
let mode = "menu";
let levelIndex = 0;
let score = 0;
let bestScore = 0;
let lives = 3;
let tick = 0;
let wideUntil = 0;
let slowUntil = 0;
let bricks = buildBricks();

window.addEventListener("keydown", (event) => {
  if (event.code === "Space" || event.key === "Enter") pressStart();
  keys.add(event.key);
});
window.addEventListener("keyup", (event) => keys.delete(event.key));
canvas.addEventListener("pointerdown", pressStart);
canvas.addEventListener("pointermove", (event) => {
  const rect = canvas.getBoundingClientRect();
  paddle.x = ((event.clientX - rect.left) / rect.width) * canvas.width - paddle.w / 2;
});

function pressStart() {
  if (mode === "playing") return;
  levelIndex = 0;
  score = 0;
  lives = 3;
  wideUntil = 0;
  slowUntil = 0;
  drops.length = 0;
  particles.length = 0;
  bricks = buildBricks();
  resetBall();
  mode = "playing";
}

function buildBricks() {
  const map = levels[levelIndex % levels.length];
  const result = [];
  const startX = 140;
  const startY = 82;
  const gap = 10;
  const w = 92;
  const h = 42;
  map.forEach((row, rowIndex) => {
    [...row].forEach((cell, colIndex) => {
      if (cell === "1" || cell === "2") {
        result.push({
          x: startX + colIndex * (w + gap),
          y: startY + rowIndex * (h + gap),
          w,
          h,
          hp: cell === "2" ? 2 : 1,
          alive: true,
          color: brickColors[rowIndex % brickColors.length]
        });
      }
    });
  });
  return result;
}

function makeStars(count) {
  const result = [];
  for (let i = 0; i < count; i++) {
    result.push({
      x: Math.random() * 900,
      y: Math.random() * 560,
      size: Math.random() * 1.8 + 0.6,
      speed: Math.random() * 0.35 + 0.08,
      twinkle: Math.random() * Math.PI * 2
    });
  }
  return result;
}

function popBrick(brick) {
  for (let i = 0; i < 14; i++) {
    particles.push({
      x: brick.x + brick.w / 2,
      y: brick.y + brick.h / 2,
      vx: (Math.random() - 0.5) * 7,
      vy: (Math.random() - 0.5) * 7 - 1.5,
      size: Math.random() * 5 + 2,
      color: brick.color,
      life: 1
    });
  }
  if (Math.random() < 0.18) {
    const total = powerups.reduce((sum, p) => sum + p.weight, 0);
    let pick = Math.random() * total;
    for (const powerup of powerups) {
      pick -= powerup.weight;
      if (pick <= 0) {
        drops.push({ x: brick.x + brick.w / 2, y: brick.y + brick.h / 2, vy: 2.6, ...powerup });
        break;
      }
    }
  }
}

function catchPowerup(drop) {
  if (drop.type === "wide") wideUntil = tick + 480;
  if (drop.type === "slow") slowUntil = tick + 360;
  if (drop.type === "life") lives = Math.min(5, lives + 1);
  for (let i = 0; i < 10; i++) {
    particles.push({
      x: drop.x,
      y: paddle.y,
      vx: (Math.random() - 0.5) * 5,
      vy: -Math.random() * 4,
      size: 2 + Math.random() * 3,
      color: themeColors.accent,
      life: 1
    });
  }
}

function loseBall() {
  lives -= 1;
  if (lives <= 0) {
    bestScore = Math.max(bestScore, score);
    mode = "over";
    return;
  }
  resetBall();
}

function update() {
  tick += 1;
  for (const star of stars) {
    star.y += star.speed;
    if (star.y > canvas.height) star.y = -2;
  }
  if (mode !== "playing") return;

  paddle.w = tick < wideUntil ? 210 : 150;
  const speedScale = (tick < slowUntil ? 0.6 : 1) * (1 + levelIndex * 0.08);
  if (keys.has("ArrowLeft")) paddle.x -= paddle.speed;
  if (keys.has("ArrowRight")) paddle.x += paddle.speed;
  paddle.x = Math.max(0, Math.min(canvas.width - paddle.w, paddle.x));
  ball.x += ball.vx * speedScale;
  ball.y += ball.vy * speedScale;

  trail.unshift({ x: ball.x, y: ball.y });
  if (trail.length > 8) trail.pop();

  if (ball.x < ball.r || ball.x > canvas.width - ball.r) ball.vx *= -1;
  if (ball.y < ball.r) ball.vy *= -1;
  if (ball.y > canvas.height + 40) loseBall();

  if (
    ball.y + ball.r > paddle.y &&
    ball.y - ball.r < paddle.y + paddle.h &&
    ball.x > paddle.x &&
    ball.x < paddle.x + paddle.w
  ) {
    ball.vy = -Math.abs(ball.vy);
    ball.vx += (ball.x - (paddle.x + paddle.w / 2)) * 0.035;
  }

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (ball.x > brick.x && ball.x < brick.x + brick.w && ball.y > brick.y && ball.y < brick.y + brick.h) {
      brick.hp -= 1;
      ball.vy *= -1;
      if (brick.hp <= 0) {
        brick.alive = false;
        score += 10;
        popBrick(brick);
      } else {
        score += 5;
      }
    }
  }

  for (let i = drops.length - 1; i >= 0; i--) {
    const drop = drops[i];
    drop.y += drop.vy;
    const caught =
      drop.y > paddle.y - 14 &&
      drop.y < paddle.y + 30 &&
      drop.x > paddle.x - 12 &&
      drop.x < paddle.x + paddle.w + 12;
    if (caught) {
      catchPowerup(drop);
      drops.splice(i, 1);
    } else if (drop.y > canvas.height + 30) {
      drops.splice(i, 1);
    }
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.18;
    p.life -= 0.025;
    if (p.life <= 0) particles.splice(i, 1);
  }

  if (bricks.every((brick) => !brick.alive)) {
    levelIndex += 1;
    bricks = buildBricks();
    resetBall();
  }
  bestScore = Math.max(bestScore, score);
  status.textContent = `Level ${levelIndex + 1} · Score ${score} · ${"❤️".repeat(lives)}`;
}

function resetBall() {
  ball.x = canvas.width / 2;
  ball.y = 430;
  ball.vx = 4.2;
  ball.vy = -5.4;
  trail.length = 0;
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, themeColors.surface);
  sky.addColorStop(1, themeColors.background);
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (const star of stars) {
    const glow = 0.35 + 0.3 * Math.sin(tick * 0.05 + star.twinkle);
    ctx.globalAlpha = glow;
    ctx.fillStyle = themeColors.text;
    ctx.beginPath();
    ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawBrick(brick) {
  ctx.save();
  ctx.shadowColor = "rgba(0, 0, 0, 0.45)";
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 4;
  const body = ctx.createLinearGradient(0, brick.y, 0, brick.y + brick.h);
  const strong = brick.hp >= 2;
  body.addColorStop(0, strong ? shade(brick.color, -20) : brick.color);
  body.addColorStop(1, shade(brick.color, strong ? -70 : -35));
  ctx.fillStyle = body;
  roundRect(brick.x, brick.y, brick.w, brick.h, 9);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = themeColors.text;
  roundRect(brick.x + 4, brick.y + 3, brick.w - 8, brick.h * 0.32, 6);
  ctx.fill();
  ctx.restore();

  ctx.textAlign = "center";
  ctx.font = "26px system-ui";
  ctx.fillText(brickEmoji, brick.x + brick.w / 2, brick.y + brick.h / 2 + 9);
  if (strong) {
    ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
    ctx.lineWidth = 2;
    roundRect(brick.x + 2, brick.y + 2, brick.w - 4, brick.h - 4, 8);
    ctx.stroke();
  }
}

function drawPaddle() {
  ctx.save();
  ctx.shadowColor = themeColors.accent;
  ctx.shadowBlur = 18;
  const body = ctx.createLinearGradient(0, paddle.y, 0, paddle.y + paddle.h);
  body.addColorStop(0, "#ffffff");
  body.addColorStop(0.35, themeColors.accent);
  body.addColorStop(1, shade(themeColors.accent, -40));
  ctx.fillStyle = body;
  roundRect(paddle.x, paddle.y, paddle.w, paddle.h, paddle.h / 2);
  ctx.fill();
  ctx.restore();
}

function drawBall() {
  for (let i = trail.length - 1; i >= 0; i--) {
    const t = trail[i];
    ctx.globalAlpha = 0.25 * (1 - i / trail.length);
    ctx.fillStyle = themeColors.accent;
    ctx.beginPath();
    ctx.arc(t.x, t.y, ball.r * (1 - i / (trail.length + 3)), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  ctx.save();
  ctx.shadowColor = "rgba(255, 255, 255, 0.6)";
  ctx.shadowBlur = 14;
  ctx.textAlign = "center";
  ctx.font = "30px system-ui";
  ctx.fillText(ballEmoji, ball.x, ball.y + 10);
  ctx.restore();
}

function drawParticles() {
  for (const p of particles) {
    ctx.globalAlpha = Math.max(p.life, 0);
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawDrops() {
  ctx.textAlign = "center";
  for (const drop of drops) {
    ctx.font = "30px system-ui";
    ctx.fillText(drop.emoji, drop.x, drop.y + Math.sin(tick * 0.15) * 2);
  }
}

function drawOverlayCard(title, line1, line2) {
  ctx.save();
  ctx.globalAlpha = 0.45;
  ctx.fillStyle = themeColors.background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.restore();
  ctx.fillStyle = themeColors.surface;
  roundRect(canvas.width / 2 - 230, 160, 460, 230, 22);
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.textAlign = "center";
  ctx.font = "44px system-ui";
  ctx.fillText(title, canvas.width / 2, 235);
  ctx.font = "24px system-ui";
  ctx.fillText(line1, canvas.width / 2, 288);
  ctx.font = "19px system-ui";
  ctx.fillText(line2, canvas.width / 2, 340);
}

function draw() {
  drawBackground();
  for (const brick of bricks) {
    if (brick.alive) drawBrick(brick);
  }
  drawPaddle();
  drawBall();
  drawDrops();
  drawParticles();

  if (mode === "menu") {
    drawOverlayCard(`${ballEmoji} Brick Breaker`, "Catch 🍭 ⏳ ❤️ powerups as they fall!", "Tap, click, or press Space to start");
    status.textContent = "Ready?";
  }
  if (mode === "over") {
    drawOverlayCard("💥 Game over!", `Score ${score} · Best ${bestScore}`, "Tap, click, or press Space to play again");
    status.textContent = `Score ${score} · Best ${bestScore}`;
  }
}

function shade(color, amount) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = Math.max(0, Math.min(255, (num >> 16) + amount));
  const g = Math.max(0, Math.min(255, ((num >> 8) & 255) + amount));
  const b = Math.max(0, Math.min(255, (num & 255) + amount));
  return `rgb(${r}, ${g}, ${b})`;
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

