  --jr-bg: #1f2937;
  --jr-surface: #111827;
  --jr-text: #fff7ed;
  --jr-accent: #fda4af;
  --jr-accent-contrast: #172033;
}
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: linear-gradient(135deg, #1f2937, #581c87 55%, #7f1d1d);
  color: #fff7ed;
}
main { width: min(94vw, 980px); }
header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}
p { margin: 0 0 5px; color: #fda4af; font-weight: 900; text-transform: uppercase; letter-spacing: 0.08em; }
h1 { margin: 0; font-size: clamp(34px, 7vw, 64px); line-height: 0.95; }
