const event = {
  name: "The Big Adventure",
  emoji: "🚀",
  targetDate: "2027-01-01T12:00:00"
};
const celebrationEmoji = ["🎉", "✨", "🚀", "⭐", "🥳"];

const eventName = document.getElementById("event-name");
const eventEmoji = document.getElementById("event-emoji");
const form = document.getElementById("date-form");
const dateInput = document.getElementById("target-date");
const message = document.getElementById("message");
const rain = document.getElementById("rain");
const stars = document.getElementById("stars");
const units = {
  days: document.getElementById("days"),
  hours: document.getElementById("hours"),
  minutes: document.getElementById("minutes"),
  seconds: document.getElementById("seconds")
};
let targetTime = resolveInitialTarget();
let previousSecond = null;
let celebrating = false;

eventName.textContent = event.name;
eventEmoji.textContent = event.emoji;
dateInput.value = formatForInput(targetTime);
buildStars();
form.addEventListener("submit", (submitEvent) => {
  submitEvent.preventDefault();
  const nextTarget = new Date(dateInput.value).getTime();
  if (!Number.isFinite(nextTarget)) {
    message.textContent = "Choose a valid date and time.";
    return;
  }
  targetTime = nextTarget;
  stopCelebration();
  updateClock();
});

function resolveInitialTarget() {
  const configured = new Date(event.targetDate).getTime();
  if (Number.isFinite(configured) && configured > Date.now()) return configured;
  return Date.now() + 7 * 24 * 60 * 60 * 1000;
}

function updateClock() {
  const remaining = Math.max(0, targetTime - Date.now());
  const totalSeconds = Math.floor(remaining / 1000);
  const values = {
    days: Math.floor(totalSeconds / 86400),
    hours: Math.floor((totalSeconds % 86400) / 3600),
    minutes: Math.floor((totalSeconds % 3600) / 60),
    seconds: totalSeconds % 60
  };
  Object.entries(values).forEach(([name, value]) => {
    units[name].textContent = String(value).padStart(2, "0");
  });
  if (previousSecond !== values.seconds) {
    const box = units.seconds.parentElement;
    box.classList.remove("tick");
    void box.offsetWidth;
    box.classList.add("tick");
    previousSecond = values.seconds;
  }
  if (remaining <= 0) startCelebration();
  else message.textContent = `${values.days} ${values.days === 1 ? "day" : "days"} until ${event.name}.`;
}

function startCelebration() {
  if (celebrating) return;
  celebrating = true;
  document.body.classList.add("celebrating");
  message.textContent = `${event.name} is here!`;
  for (let index = 0; index < 42; index += 1) {
    const piece = document.createElement("i");
    piece.textContent = celebrationEmoji[index % celebrationEmoji.length];
    piece.style.left = `${(index * 43) % 100}%`;
    piece.style.animationDelay = `${(index % 9) * -0.22}s`;
    piece.style.animationDuration = `${1.8 + (index % 5) * 0.18}s`;
    rain.append(piece);
  }
}

function stopCelebration() {
  celebrating = false;
  document.body.classList.remove("celebrating");
  rain.innerHTML = "";
}

function buildStars() {
  for (let index = 0; index < 64; index += 1) {
    const star = document.createElement("i");
    star.style.left = `${(index * 47) % 100}%`;
    star.style.top = `${(index * 71) % 100}%`;
    star.style.animationDelay = `${(index % 11) * -0.15}s`;
    stars.append(star);
  }
}

function formatForInput(time) {
  const date = new Date(time);
  const local = new Date(time - date.getTimezoneOffset() * 60 * 1000);
  return local.toISOString().slice(0, 16);
}

updateClock();
setInterval(updateClock, 250);

