const options = ["Pizza", "Movie", "Dance", "Draw", "Build", "Snack"];
const sliceColorTokens = ["--jr-surface", "--jr-accent", "--jr-bg", "--jr-surface", "--jr-accent", "--jr-bg"];

const canvas = document.getElementById("wheel");
const ctx = canvas.getContext("2d");
const spinButton = document.getElementById("spin");
const result = document.getElementById("result");
const themeColors = {
  text: readThemeToken("--jr-text"),
  accent: readThemeToken("--jr-accent"),
  accentContrast: readThemeToken("--jr-accent-contrast")
};
const colors = sliceColorTokens.map(readThemeToken);
let angle = 0;
let velocity = 0.02;
let spinning = false;

spinButton.addEventListener("click", spin);
canvas.addEventListener("pointerdown", spin);

function spin() {
  velocity = 0.34 + Math.random() * 0.22;
  spinning = true;
  result.textContent = "Spinning...";
}

function update() {
  angle += velocity;
  if (spinning) {
    velocity *= 0.986;
    if (velocity < 0.006) {
      spinning = false;
      velocity = 0.003;
      result.textContent = `Winner: ${currentOption()}!`;
    }
  } else {
    velocity = 0.003;
  }
}

function currentOption() {
  const slice = (Math.PI * 2) / options.length;
  const pointerAngle = (Math.PI * 1.5 - angle + Math.PI * 2) % (Math.PI * 2);
  return options[Math.floor(pointerAngle / slice) % options.length];
}

function draw() {
  const center = canvas.width / 2;
  const radius = center - 18;
  const slice = (Math.PI * 2) / options.length;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  options.forEach((option, index) => {
    const start = angle + index * slice;
    ctx.beginPath();
    ctx.moveTo(center, center);
    ctx.arc(center, center, radius, start, start + slice);
    ctx.closePath();
    ctx.fillStyle = colors[index % colors.length];
    ctx.fill();
    ctx.save();
    ctx.translate(center, center);
    ctx.rotate(start + slice / 2);
    ctx.fillStyle = sliceColorTokens[index] === "--jr-accent"
      ? themeColors.accentContrast
      : themeColors.text;
    ctx.font = "bold 24px system-ui";
    ctx.textAlign = "right";
    ctx.fillText(option, radius - 24, 8);
    ctx.restore();
  });
  ctx.fillStyle = themeColors.accent;
  ctx.beginPath();
  ctx.moveTo(center, 18);
  ctx.lineTo(center - 18, 58);
  ctx.lineTo(center + 18, 58);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.beginPath();
  ctx.arc(center, center, 24, 0, Math.PI * 2);
  ctx.fill();
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

