  if (tick > nextPowerup) {
    const powerup = powerups[Math.floor(Math.random() * powerups.length)];
    falling.push({ ...powerup, points: 0, x: 40 + Math.random() * (canvas.width - 80), y: -30, vy: 2.6, spin: 0 });
    nextPowerup = tick + 620 + Math.random() * 500;
  }
  if (tick > nextBird) {
    const fromLeft = Math.random() < 0.5;
    birds.push({
      x: fromLeft ? -50 : canvas.width + 50,
      y: 105 + Math.random() * 30,
      vx: fromLeft ? 3 : -3,
      flap: Math.random() * Math.PI * 2,
      dropped: false
    });
    nextBird = tick + 850 + Math.random() * 650;
  }

  for (let i = birds.length - 1; i >= 0; i--) {
    const bird = birds[i];
    bird.x += bird.vx;
    bird.flap += 0.22;
    if (!bird.dropped && Math.abs(bird.x - (basket.x + basket.w / 2)) < 26) {
      bird.dropped = true;
      falling.push({ ...badItems[0], x: bird.x, y: bird.y + 24, vy: 4.4, spin: 0 });
    }
    if (bird.x < -70 || bird.x > canvas.width + 70) birds.splice(i, 1);
  }

  const slowFactor = tick < slowUntil ? 0.55 : 1;
  for (const item of falling) {
    item.y += item.vy * slowFactor;
    item.spin += 0.05;
    const caught =
      item.y > basket.y - 24 &&
      item.y < basket.y + 36 &&
      item.x > basket.x - 10 &&
      item.x < basket.x + basket.w + 10;
    if (caught) {
      item.done = true;
      if (item.type) {
        catchPowerup(item);
      } else if (item.points > 0) {
        score += item.points;
        bestScore = Math.max(bestScore, score);
        basket.bounce = 0.3;
        burst(item.x, basket.y, themeColors.accent, 10);
        popup(item.x, basket.y - 30, `+${item.points}`, themeColors.accent);
      } else {
        shake = 13;
        burst(item.x, basket.y, themeColors.text, 16);
        popup(item.x, basket.y - 30, "💥", themeColors.text);
        loseLife();
      }
    } else if (item.y > canvas.height + 40) {
      item.done = true;
      if (item.points > 0) {
        popup(item.x, canvas.height - 40, "Miss!", themeColors.text);
        loseLife();
      }
    }
  }
  for (let i = falling.length - 1; i >= 0; i--) {
    if (falling[i].done) falling.splice(i, 1);
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.12;
    p.life -= 0.03;
    if (p.life <= 0) particles.splice(i, 1);
  }
  for (let i = popups.length - 1; i >= 0; i--) {
    const p = popups[i];
    p.y -= 1.1;
    p.life -= 0.025;
    if (p.life <= 0) popups.splice(i, 1);
  }
}

function shade(color, amount) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = Math.max(0, Math.min(255, (num >> 16) + amount));
  const g = Math.max(0, Math.min(255, ((num >> 8) & 255) + amount));
  const b = Math.max(0, Math.min(255, (num & 255) + amount));
  return `rgb(${r}, ${g}, ${b})`;
}

function withAlpha(color, alpha) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = num >> 16;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function drawCard(title, line1, line2) {
  ctx.fillStyle = withAlpha(themeColors.background, 0.45);
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  ctx.fillStyle = themeColors.surface;
  ctx.beginPath();
  ctx.roundRect(canvas.width / 2 - 220, 150, 440, 210, 22);
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.textAlign = "center";
  ctx.font = "44px system-ui";
  ctx.fillText(title, canvas.width / 2, 220);
  ctx.font = "24px system-ui";
  ctx.fillText(line1, canvas.width / 2, 268);
  ctx.font = "19px system-ui";
  ctx.fillText(line2, canvas.width / 2, 318);
}

function draw() {
  ctx.save();
  if (shake > 0.5) {
    ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
  }

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, themeColors.surface);
  sky.addColorStop(1, shade(themeColors.surface, -36));
  ctx.fillStyle = sky;
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);

  for (const cloud of clouds) {
    ctx.fillStyle = withAlpha(themeColors.surface, 0.55);
    ctx.beginPath();
    ctx.ellipse(cloud.x, cloud.y, cloud.size, cloud.size * 0.42, 0, 0, Math.PI * 2);
    ctx.ellipse(cloud.x + cloud.size * 0.55, cloud.y + 6, cloud.size * 0.6, cloud.size * 0.3, 0, 0, Math.PI * 2);
    ctx.ellipse(cloud.x - cloud.size * 0.55, cloud.y + 7, cloud.size * 0.55, cloud.size * 0.28, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  const groundGradient = ctx.createLinearGradient(0, 486, 0, canvas.height);
  groundGradient.addColorStop(0, shade(themeColors.accent, 20));
  groundGradient.addColorStop(1, shade(themeColors.accent, -50));
  ctx.fillStyle = groundGradient;
  ctx.fillRect(-20, 486, canvas.width + 40, canvas.height - 486 + 20);
  ctx.fillStyle = withAlpha(themeColors.surface, 0.4);
  ctx.fillRect(-20, 486, canvas.width + 40, 3);

  ctx.textAlign = "center";
  for (const bird of birds) {
    ctx.save();
    if (bird.vx > 0) ctx.translate(bird.x, 0), ctx.scale(-1, 1), ctx.translate(-bird.x, 0);
    ctx.font = `${34 + Math.sin(bird.flap) * 3}px system-ui`;
    ctx.fillText(enemyEmoji, bird.x, bird.y + Math.sin(bird.flap) * 4);
    ctx.restore();
  }

  for (const item of falling) {
    ctx.fillStyle = withAlpha(themeColors.text, 0.12);
    ctx.beginPath();
    const drop = Math.max(0, Math.min(1, item.y / 460));
    ctx.ellipse(item.x, 492, 20 * drop, 5 * drop, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.save();
    ctx.translate(item.x, item.y);
    ctx.rotate(Math.sin(item.spin) * 0.25);
    ctx.font = "38px system-ui";
    ctx.fillText(item.emoji, 0, 0);
    ctx.restore();
  }

  for (const p of particles) {
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  ctx.fillStyle = withAlpha(themeColors.text, 0.2);
  ctx.beginPath();
  ctx.ellipse(basket.x + basket.w / 2, 494, 42, 8, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.save();
  ctx.translate(basket.x + basket.w / 2, basket.y + 42);
  ctx.rotate(Math.max(-0.22, Math.min(0.22, basket.lean)));
  ctx.scale(1 + basket.bounce * 0.4, 1 - basket.bounce * 0.3);
  ctx.font = "58px system-ui";
  ctx.fillText(basketEmoji, 0, 0);
  ctx.restore();

  for (const p of popups) {
    ctx.globalAlpha = Math.max(0, p.life);
    ctx.fillStyle = p.color;
    ctx.font = "bold 26px system-ui";
    ctx.fillText(p.text, p.x, p.y);
  }
  ctx.globalAlpha = 1;

  if (tick < slowUntil && mode === "playing") {
    ctx.fillStyle = withAlpha(themeColors.accent, 0.08);
    ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  }
  if (hurtFlash > 0.04) {
    ctx.fillStyle = `rgba(220, 38, 38, ${hurtFlash * 0.28})`;
    ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  }

  if (mode === "menu") {
    drawCard(`${basketEmoji} Emoji Catcher`, `Catch treats · grab ❤️ ⏳ · dodge ${enemyEmoji} bombs!`, "Tap, click, or press Space to play");
  }
  if (mode === "over") {
    drawCard(`${basketEmoji} Game over!`, `Score ${score} · Best ${bestScore}`, "Tap, click, or press Space to play again");
  }
  ctx.restore();

  hud.textContent = mode === "playing"
    ? `Score ${score} · ${"❤️".repeat(Math.max(0, lives))}${tick < slowUntil ? " · ⏳" : ""}`
    : `Score ${score} · Best ${bestScore}`;
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

* { box-sizing: border-box; }
/* jr-theme-tokens-v1 */
:root {
