}
body { background: var(--jr-bg); color: var(--jr-text); }
strong { background: var(--jr-accent); color: var(--jr-accent-contrast); border-color: var(--jr-accent); }
canvas { background: var(--jr-surface); border-color: var(--jr-accent); }

// ⭐ CHANGE THESE
const hero = { emoji: "🐱", jumpPower: 16, gravity: 0.82 };
const obstacles = ["🌵", "🪨", "🚧"];
const groundEmoji = "🌿";
const cloudEmoji = "☁️";
const coinEmoji = "⭐";
const shieldEmoji = "🛡️";
const enemyEmoji = "🦅";

const GROUND_Y = 350;
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const scoreLabel = document.getElementById("score");
const themeColors = {
  background: readThemeToken("--jr-bg"),
  surface: readThemeToken("--jr-surface"),
  text: readThemeToken("--jr-text"),
  accent: readThemeToken("--jr-accent")
};
const player = { x: 120, y: GROUND_Y, vy: 0, size: 56, onGround: true, squash: 0 };
const clouds = Array.from({ length: 4 }, (_, i) => ({
  x: i * 260 + 60,
  y: 60 + (i % 2) * 55,
  size: 34 + (i % 3) * 12,
  speed: 0.25 + (i % 3) * 0.12
}));
const particles = [];
const activeObstacles = [];
const coins = [];
const enemies = [];
const pickups = [];
let mode = "menu";
let speed = 6;
let score = 0;
let bestScore = 0;
let tick = 0;
let nextObstacle = 90;
let nextCoin = 150;
let nextEnemy = 700;
let nextPickup = 1100;
let shield = false;
let shake = 0;

window.addEventListener("keydown", (event) => {
  if (event.code === "Space" || event.key === "ArrowUp") jump();
});
canvas.addEventListener("pointerdown", jump);

function jump() {
  if (mode !== "playing") {
    reset();
    mode = "playing";
    return;
  }
  if (!player.onGround) return;
  player.vy = -hero.jumpPower;
  player.onGround = false;
  player.squash = -0.18;
}

function reset() {
  activeObstacles.length = 0;
  particles.length = 0;
  coins.length = 0;
  enemies.length = 0;
  pickups.length = 0;
  player.y = GROUND_Y;
  player.vy = 0;
  score = 0;
  speed = 6;
  tick = 0;
  nextObstacle = 90;
  nextCoin = 150;
  nextEnemy = 700;
  nextPickup = 1100;
  shield = false;
  updateScoreLabel();
}

function puff(x, y, count, color) {
  for (let i = 0; i < count; i++) {
    particles.push({
      x: x + (Math.random() - 0.5) * 22,
      y,
      vx: (Math.random() - 0.5) * 3 - speed * 0.25,
      vy: -Math.random() * 2.4,
      size: 3 + Math.random() * 4,
      color,
      life: 1
    });
  }
}

function crash() {
  if (shield) {
    shield = false;
    puff(player.x, player.y, 14, withAlpha(themeColors.surface, 0.9));
    return false;
  }
  mode = "over";
  shake = 14;
  puff(player.x, player.y, 18, withAlpha(themeColors.accent, 0.9));
  bestScore = Math.max(bestScore, Math.floor(score));
  return true;
}

function update() {
  tick += 1;
  shake *= 0.85;
  for (const cloud of clouds) {
    cloud.x -= cloud.speed;
    if (cloud.x < -70) cloud.x = canvas.width + 70;
  }
  if (mode !== "playing") return;

  score += 0.04;
  bestScore = Math.max(bestScore, Math.floor(score));
  speed = Math.min(16, 6 + score * 0.05);

  const wasAirborne = !player.onGround;
  player.vy += hero.gravity;
  player.y += player.vy;
  if (player.y > GROUND_Y) {
    player.y = GROUND_Y;
    player.vy = 0;
    player.onGround = true;
    if (wasAirborne) {
      player.squash = 0.22;
      puff(player.x, GROUND_Y + 22, 7, withAlpha(themeColors.surface, 0.75));
    }
  }
  player.squash *= 0.86;

  if (tick > nextObstacle) {
    activeObstacles.push({
      x: canvas.width + 40,
      y: 364,
      emoji: obstacles[Math.floor(Math.random() * obstacles.length)],
      size: 46,
      wobble: Math.random() * Math.PI * 2
    });
    nextObstacle = tick + (400 + Math.random() * 320) / speed;
  }
  if (tick > nextCoin) {
    const baseY = 210 + Math.random() * 90;
    for (let i = 0; i < 3; i++) {
      coins.push({ x: canvas.width + 60 + i * 46, y: baseY - Math.sin((i / 2) * Math.PI) * 26 });
    }
    nextCoin = tick + (900 + Math.random() * 700) / speed;
  }
  if (tick > nextEnemy) {
    enemies.push({ x: canvas.width + 60, y: 235 + Math.random() * 30, flap: Math.random() * Math.PI * 2 });
    nextEnemy = tick + (2200 + Math.random() * 1400) / speed;
  }
  if (tick > nextPickup && !shield) {
    pickups.push({ x: canvas.width + 60, y: 265 });
    nextPickup = tick + (3200 + Math.random() * 1800) / speed;
  }

  for (const obstacle of activeObstacles) obstacle.x -= speed;
  while (activeObstacles[0]?.x < -80) activeObstacles.shift();
  for (let i = activeObstacles.length - 1; i >= 0; i--) {
    const obstacle = activeObstacles[i];
    if (Math.abs(player.x - obstacle.x) < 38 && Math.abs(player.y - obstacle.y) < 44) {
      if (crash()) return;
      activeObstacles.splice(i, 1);
    }
  }

  for (let i = enemies.length - 1; i >= 0; i--) {
    const enemy = enemies[i];
    enemy.x -= speed * 1.25;
    enemy.flap += 0.2;
    if (enemy.x < -80) {
      enemies.splice(i, 1);
      continue;
    }
    if (Math.abs(player.x - enemy.x) < 36 && Math.abs(player.y - enemy.y) < 40) {
      if (crash()) return;
      enemies.splice(i, 1);
    }
  }

  for (let i = coins.length - 1; i >= 0; i--) {
    const coin = coins[i];
    coin.x -= speed;
    if (coin.x < -40) {
      coins.splice(i, 1);
      continue;
    }
    if (Math.abs(player.x - coin.x) < 36 && Math.abs(player.y - coin.y) < 42) {
      score += 5;
      puff(coin.x, coin.y, 8, withAlpha(themeColors.accent, 0.9));
      coins.splice(i, 1);
    }
  }

  for (let i = pickups.length - 1; i >= 0; i--) {
    const pickup = pickups[i];
    pickup.x -= speed;
    if (pickup.x < -40) {
      pickups.splice(i, 1);
      continue;
    }
    if (Math.abs(player.x - pickup.x) < 38 && Math.abs(player.y - pickup.y) < 44) {
      shield = true;
      puff(pickup.x, pickup.y, 12, withAlpha(themeColors.surface, 0.9));
      pickups.splice(i, 1);
    }
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.05;
    p.life -= 0.03;
    if (p.life <= 0) particles.splice(i, 1);
  }
  updateScoreLabel();
}

function updateScoreLabel() {
  scoreLabel.textContent = `Score ${Math.floor(score)} · Best ${bestScore}${shield ? " · 🛡️" : ""}`;
}

function shade(color, amount) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = Math.max(0, Math.min(255, (num >> 16) + amount));
  const g = Math.max(0, Math.min(255, ((num >> 8) & 255) + amount));
  const b = Math.max(0, Math.min(255, (num & 255) + amount));
  return `rgb(${r}, ${g}, ${b})`;
}

function withAlpha(color, alpha) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = num >> 16;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function wrap(x, width) {
  return ((x % width) + width) % width;
}

function drawHills(baseY, height, step, offsetSpeed, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, canvas.height);
  const shift = wrap(tick * offsetSpeed, step * 2);
  for (let x = -step * 2; x <= canvas.width + step * 2; x += 4) {
    const y = baseY - Math.abs(Math.sin(((x + shift) / step) * Math.PI)) * height;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(canvas.width, canvas.height);
  ctx.closePath();
  ctx.fill();
}

function drawCard(title, line1, line2) {
  ctx.fillStyle = withAlpha(themeColors.background, 0.45);
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  ctx.fillStyle = themeColors.surface;
  ctx.beginPath();
  ctx.roundRect(canvas.width / 2 - 220, 140, 440, 210, 22);
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.font = "44px system-ui";
  ctx.fillText(title, canvas.width / 2, 210);
  ctx.font = "24px system-ui";
  ctx.fillText(line1, canvas.width / 2, 258);
  ctx.font = "19px system-ui";
  ctx.fillText(line2, canvas.width / 2, 308);
}

function draw() {
  ctx.save();
  if (shake > 0.5) {
    ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
  }

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, themeColors.surface);
  sky.addColorStop(1, themeColors.background);
  ctx.fillStyle = sky;
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);

  const sunGlow = ctx.createRadialGradient(760, 90, 10, 760, 90, 130);
  sunGlow.addColorStop(0, themeColors.accent);
  sunGlow.addColorStop(1, withAlpha(themeColors.surface, 0));
  ctx.globalAlpha = 0.55;
  ctx.fillStyle = sunGlow;
  ctx.fillRect(620, -50, 290, 290);
  ctx.globalAlpha = 1;
  ctx.fillStyle = themeColors.accent;
  ctx.beginPath();
  ctx.arc(760, 90, 46, 0, Math.PI * 2);
  ctx.fill();

  ctx.textAlign = "center";
  for (const cloud of clouds) {
    ctx.globalAlpha = 0.85;
    ctx.font = `${cloud.size}px system-ui`;
    ctx.fillText(cloudEmoji, cloud.x, cloud.y);
  }
  ctx.globalAlpha = 1;

  drawHills(400, 130, 340, 0.5, shade(themeColors.background, 26));
  drawHills(412, 74, 210, 1.1, shade(themeColors.background, 12));

  const groundGradient = ctx.createLinearGradient(0, 414, 0, canvas.height);
  groundGradient.addColorStop(0, shade(themeColors.accent, 10));
  groundGradient.addColorStop(1, shade(themeColors.accent, -60));
  ctx.fillStyle = groundGradient;
  ctx.fillRect(-20, 414, canvas.width + 40, canvas.height - 414 + 20);
  ctx.fillStyle = withAlpha(themeColors.surface, 0.35);
  ctx.fillRect(-20, 414, canvas.width + 40, 3);

  ctx.font = "28px system-ui";
  const plantStep = 76;
  for (let i = 0; i < Math.ceil(canvas.width / plantStep) + 2; i++) {
    const x = wrap(i * plantStep - tick * speed * 0.9, canvas.width + plantStep * 2) - plantStep;
    ctx.globalAlpha = 0.9;
    ctx.fillText(groundEmoji, x, 442 + (i % 2) * 5);
  }
  ctx.globalAlpha = 1;

  for (const coin of coins) {
    ctx.font = "30px system-ui";
    ctx.fillText(coinEmoji, coin.x, coin.y + Math.sin(tick * 0.12 + coin.x) * 3);
  }
  for (const pickup of pickups) {
    ctx.font = "34px system-ui";
    ctx.fillText(shieldEmoji, pickup.x, pickup.y + Math.sin(tick * 0.1) * 4);
  }
  for (const enemy of enemies) {
    ctx.font = `${40 + Math.sin(enemy.flap) * 4}px system-ui`;
    ctx.fillText(enemyEmoji, enemy.x, enemy.y + Math.sin(enemy.flap) * 5);
  }

  for (const p of particles) {
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  for (const obstacle of activeObstacles) {
    ctx.fillStyle = withAlpha(themeColors.text, 0.22);
    ctx.beginPath();
    ctx.ellipse(obstacle.x, 410, 26, 6, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.font = `${obstacle.size}px system-ui`;
    ctx.fillText(obstacle.emoji, obstacle.x, obstacle.y + Math.sin(tick * 0.1 + obstacle.wobble) * 1.5);
  }

  const airborne = !player.onGround;
  const shadowScale = Math.max(0.35, 1 - (GROUND_Y - player.y) / 260);
  ctx.fillStyle = withAlpha(themeColors.text, 0.25);
  ctx.beginPath();
  ctx.ellipse(player.x, 410, 30 * shadowScale, 7 * shadowScale, 0, 0, Math.PI * 2);
  ctx.fill();
  if (shield) {
    ctx.strokeStyle = withAlpha(themeColors.surface, 0.5 + Math.sin(tick * 0.15) * 0.2);
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(player.x, player.y - 8, 42, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.save();
  ctx.translate(player.x, player.y);
  if (airborne) ctx.rotate(Math.max(-0.3, Math.min(0.35, player.vy * 0.03)));
  ctx.scale(1 - player.squash * 0.6, 1 + player.squash);
  ctx.font = `${player.size}px system-ui`;
  ctx.fillText(hero.emoji, 0, 0);
  ctx.restore();

  if (mode === "menu") {
    drawCard(`${hero.emoji} Emoji Runner`, `Grab ${coinEmoji} and ${shieldEmoji} · dodge ${enemyEmoji}!`, "Tap, click, or press Space to run");
  }
  if (mode === "over") {
    drawCard("💥 Game over!", `Score ${Math.floor(score)} · Best ${bestScore}`, "Tap, click, or press Space to run again");
  }
  ctx.restore();
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

updateScoreLabel();
loop();

