// ⭐ CHANGE THESE
const deckTitle = "Amazing Animal Facts";
const deck = [
  { front: "Which animal has fingerprints like a human?", back: "A koala 🐨" },
  { front: "What is a group of flamingos called?", back: "A flamboyance 🦩" },
  { front: "Which mammal can truly fly?", back: "A bat 🦇" },
  { front: "How many hearts does an octopus have?", back: "Three hearts 🐙" },
  { front: "Which bird can fly backward?", back: "A hummingbird 🌺" },
  { front: "What do sea otters hold while sleeping?", back: "Each other's paws 🦦" }
];

const title = document.getElementById("deck-title");
const score = document.getElementById("score");
const progress = document.getElementById("progress");
const study = document.getElementById("study");
const finished = document.getElementById("finished");
const position = document.getElementById("position");
const card = document.getElementById("card");
const sideLabel = document.getElementById("side-label");
const cardText = document.getElementById("card-text");
const reviewButton = document.getElementById("review");
const knewButton = document.getElementById("knew");
const summary = document.getElementById("summary");
const reviewMissedButton = document.getElementById("review-missed");
const restartButton = document.getElementById("restart");
const shuffleButton = document.getElementById("shuffle");
let cards = [];
let index = 0;
let flipped = false;
let knew = 0;
let missed = [];

title.textContent = deckTitle;
card.addEventListener("click", flipCard);
knewButton.addEventListener("click", () => rate(true));
reviewButton.addEventListener("click", () => rate(false));
restartButton.addEventListener("click", () => start(deck));
reviewMissedButton.addEventListener("click", () => start(missed.length ? missed : deck));
shuffleButton.addEventListener("click", () => start(shuffle(cards.length ? cards : deck)));
window.addEventListener("keydown", (event) => {
  if (finished.hidden === false) return;
  if (event.code === "Space") {
    event.preventDefault();
    flipCard();
  }
  if (event.key === "ArrowRight" && flipped) rate(true);
  if (event.key === "ArrowLeft" && flipped) rate(false);
});

function start(nextDeck) {
  cards = [...nextDeck];
  index = 0;
  flipped = false;
  knew = 0;
  missed = [];
  study.hidden = false;
  finished.hidden = true;
  shuffleButton.hidden = false;
  renderCard();
}

function flipCard() {
  if (!cards[index]) return;
  flipped = !flipped;
  renderCard();
}

function rate(didKnow) {
  if (!flipped) return;
  if (didKnow) knew += 1;
  else missed.push(cards[index]);
  index += 1;
  flipped = false;
  if (index >= cards.length) showFinished();
  else renderCard();
}

function renderCard() {
  const current = cards[index];
  position.textContent = `Card ${index + 1} of ${cards.length}`;
  sideLabel.textContent = flipped ? "Answer" : "Question";
  cardText.textContent = flipped ? current.back : current.front;
  card.classList.toggle("answer", flipped);
  card.setAttribute("aria-label", `${flipped ? "Answer" : "Question"}: ${flipped ? current.back : current.front}. Press to flip.`);
  knewButton.disabled = !flipped;
  reviewButton.disabled = !flipped;
  score.textContent = `Know ${knew} · Review ${missed.length}`;
  progress.style.width = `${(index / cards.length) * 100}%`;
  card.animate(
    [{ opacity: 0.25, transform: "translateX(16px)" }, { opacity: 1, transform: "translateX(0)" }],
    { duration: 260, easing: "ease-out" }
  );
}

function showFinished() {
  study.hidden = true;
  finished.hidden = false;
  shuffleButton.hidden = true;
  progress.style.width = "100%";
  score.textContent = `Know ${knew} · Review ${missed.length}`;
  summary.textContent = missed.length
    ? `You knew ${knew} of ${cards.length}. ${missed.length} tricky ${missed.length === 1 ? "card is" : "cards are"} ready for another look.`
    : `You knew all ${cards.length} cards. Brilliant work!`;
  reviewMissedButton.hidden = missed.length === 0;
  restartButton.focus();
}

function shuffle(items) {
  return items
    .map((item) => ({ item, order: Math.random() }))
    .sort((left, right) => left.order - right.order)
    .map(({ item }) => item);
}

start(shuffle(deck));

