@keyframes flip { 50% { transform: rotateY(92deg) translateY(-8px); } }
@keyframes fall {
  to { transform: translateY(110vh) rotate(360deg); opacity: 0.2; }
}

// ⭐ CHANGE THESE
const explorerEmoji = "🧭";
const wallEmoji = "🌲";
const ghostEmoji = "👻";
const gemEmoji = "💎";
const levels = [
  [
    "#############",
    "#P..........#",
    "#.#######.#.#",
    "#....*....#.#",
    "#########.#.#",
    "#E....#..M..#",
    "#..#.##..##.#",
    "#..*.D.....K#",
    "#############"
  ],
  [
    "#############",
    "#P......#..K#",
    "#.#.###.##..#",
    "#...#.#.#..D#",
    "#.###..*..#.#",
    "#..M..#.#.#.#",
    "#.#.#.#.#.#.#",
    "#...#..*..#E#",
    "#############"
  ],
  [
    "#############",
    "#P#...#.....#",
    "#.#.#K#.#.#.#",
    "#...#..D#...#",
    "#######.#.#.#",
    "#...*...#.M.#",
    "#.##.##...#.#",
    "#E....*...#.#",
    "#############"
  ]
];

const canvas = document.getElementById("maze");
const ctx = canvas.getContext("2d");
const status = document.getElementById("status");
const restartButton = document.getElementById("restart");
const themeColors = {
  background: readThemeToken("--jr-bg"),
  surface: readThemeToken("--jr-surface"),
  text: readThemeToken("--jr-text"),
  accent: readThemeToken("--jr-accent")
};
const directions = {
  up: [0, -1],
  down: [0, 1],
  left: [-1, 0],
  right: [1, 0]
};
const particles = [];
let mode = "menu";
let levelIndex = 0;
let map = [];
let ghosts = [];
let start = { x: 1, y: 1 };
let player = { x: 1, y: 1 };
let drawn = { x: 1, y: 1 };
let bump = { x: 0, y: 0 };
let keys = 0;
let lives = 3;
let score = 0;
let steps = 0;
let message = "";
let hurtFlash = 0;
let tick = 0;

window.addEventListener("keydown", (event) => {
  if (mode !== "playing") {
    if (event.code === "Space" || event.key === "Enter") startGame();
    return;
  }
  const keyDirections = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right" };
  const direction = keyDirections[event.key];
  if (!direction) return;
  event.preventDefault();
  move(direction);
});
canvas.addEventListener("pointerdown", () => {
  if (mode !== "playing") startGame();
});
document.querySelectorAll("[data-move]").forEach((button) => {
  button.addEventListener("click", () => {
    if (mode === "playing") move(button.dataset.move);
  });
});
restartButton.addEventListener("click", () => {
  if (mode === "playing") loadLevel();
});

function startGame() {
  levelIndex = 0;
  lives = 3;
  score = 0;
  mode = "playing";
  loadLevel();
}

function loadLevel() {
  map = levels[levelIndex].map((row) => [...row]);
  ghosts = [];
  keys = 0;
  steps = 0;
  message = "";
  map.forEach((row, y) => row.forEach((cell, x) => {
    if (cell === "P") {
      start = { x, y };
      player = { x, y };
      drawn = { x, y };
      map[y][x] = ".";
    }
    if (cell === "M") {
      ghosts.push({ x, y, fx: x, dir: 1 });
      map[y][x] = ".";
    }
  }));
  updateStatus();
}

function move(direction) {
  const [dx, dy] = directions[direction];
  const next = { x: player.x + dx, y: player.y + dy };
  const cell = map[next.y]?.[next.x] ?? "#";
  if (cell === "#" || (cell === "D" && keys === 0)) {
    message = cell === "#" ? "A wall blocks the way." : "The door is locked! Find 🗝️";
    bump = { x: dx * 0.22, y: dy * 0.22 };
    updateStatus();
    return;
  }
  player = next;
  steps += 1;
  message = "";
  if (cell === "K") {
    keys += 1;
    map[next.y][next.x] = ".";
    message = "Key found! 🗝️";
    sparkle(next.x, next.y, themeColors.accent);
  }
  if (cell === "*") {
    score += 25;
    map[next.y][next.x] = ".";
    message = `${gemEmoji} +25!`;
    sparkle(next.x, next.y, themeColors.accent);
  }
  if (cell === "D") {
    keys -= 1;
    map[next.y][next.x] = ".";
    message = "The door creaks open! 🚪";
    sparkle(next.x, next.y, themeColors.surface);
  }
  if (cell === "E") finishLevel();
  updateStatus();
}

function finishLevel() {
  score += 50;
  sparkle(player.x, player.y, themeColors.accent);
  sparkle(player.x, player.y, themeColors.surface);
  if (levelIndex < levels.length - 1) {
    levelIndex += 1;
    message = `Level complete in ${steps} steps! ⭐ +50`;
    setTimeout(loadLevel, 900);
  } else {
    message = "Every maze explored! 🏆";
    mode = "won";
  }
}

function ghostCaught() {
  lives -= 1;
  hurtFlash = 1;
  sparkle(player.x, player.y, themeColors.text);
  if (lives <= 0) {
    message = `${ghostEmoji} Got you!`;
    mode = "over";
    return;
  }
  message = `${ghostEmoji} Got you! Back to the start.`;
  player = { ...start };
  drawn = { ...start };
  updateStatus();
}

function updateStatus() {
  status.textContent = message || `Level ${levelIndex + 1} · ${"❤️".repeat(Math.max(0, lives))} · 🗝️ ${keys} · ${gemEmoji} ${score}`;
}

function sparkle(cellX, cellY, color) {
  const cellWidth = canvas.width / map[0].length;
  const cellHeight = canvas.height / map.length;
  for (let i = 0; i < 16; i++) {
    const angle = (Math.PI * 2 * i) / 16;
    particles.push({
      x: cellX * cellWidth + cellWidth / 2,
      y: cellY * cellHeight + cellHeight / 2,
      vx: Math.cos(angle) * (1.4 + Math.random() * 2),
      vy: Math.sin(angle) * (1.4 + Math.random() * 2),
      size: 2 + Math.random() * 3,
      color,
      life: 1
    });
  }
}

function updateGhosts() {
  for (const ghost of ghosts) {
    ghost.fx += ghost.dir * 0.035;
    const ahead = ghost.dir > 0 ? Math.ceil(ghost.fx) : Math.floor(ghost.fx);
    if ((map[ghost.y]?.[ahead] ?? "#") !== "." && (map[ghost.y]?.[ahead] ?? "#") !== "*") {
      ghost.dir *= -1;
      ghost.fx = Math.round(ghost.fx);
    }
    if (mode === "playing" && Math.abs(ghost.fx - player.x) < 0.55 && ghost.y === player.y) {
      ghostCaught();
    }
  }
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function shade(color, amount) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = Math.max(0, Math.min(255, (num >> 16) + amount));
  const g = Math.max(0, Math.min(255, ((num >> 8) & 255) + amount));
  const b = Math.max(0, Math.min(255, (num & 255) + amount));
  return `rgb(${r}, ${g}, ${b})`;
}

function withAlpha(color, alpha) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
  const num = parseInt(full, 16);
  if (Number.isNaN(num)) return color;
  const r = num >> 16;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function drawCard(title, line1, line2) {
  ctx.fillStyle = withAlpha(themeColors.background, 0.5);
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = themeColors.surface;
  roundRect(canvas.width / 2 - 230, 150, 460, 220, 22);
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "42px system-ui";
  ctx.fillText(title, canvas.width / 2, 210);
  ctx.font = "23px system-ui";
  ctx.fillText(line1, canvas.width / 2, 262);
  ctx.font = "19px system-ui";
  ctx.fillText(line2, canvas.width / 2, 316);
}

function draw() {
  tick += 1;
  hurtFlash *= 0.93;
  updateGhosts();
  const cellWidth = canvas.width / map[0].length;
  const cellHeight = canvas.height / map.length;
  const emojiSize = Math.min(cellWidth, cellHeight);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, shade(themeColors.background, 14));
  sky.addColorStop(1, shade(themeColors.background, -18));
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  map.forEach((row, y) => row.forEach((cell, x) => {
    const px = x * cellWidth;
    const py = y * cellHeight;
    const centerX = px + cellWidth / 2;
    const centerY = py + cellHeight / 2;
    if (cell === "#") {
      const body = ctx.createLinearGradient(0, py, 0, py + cellHeight);
      body.addColorStop(0, shade(themeColors.accent, 20));
      body.addColorStop(1, shade(themeColors.accent, -50));
      ctx.fillStyle = body;
      roundRect(px + 1.5, py + 1.5, cellWidth - 3, cellHeight - 3, 8);
      ctx.fill();
      ctx.fillStyle = withAlpha(themeColors.surface, 0.18);
      roundRect(px + 4, py + 3.5, cellWidth - 8, cellHeight * 0.28, 5);
      ctx.fill();
      ctx.font = `${emojiSize * 0.52}px system-ui`;
      ctx.fillText(wallEmoji, centerX, centerY + 1);
    } else {
      ctx.fillStyle = themeColors.surface;
      ctx.globalAlpha = (x + y) % 2 ? 0.55 : 0.75;
      roundRect(px + 2, py + 2, cellWidth - 4, cellHeight - 4, 7);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    if (cell === "E") {
      const pulse = 0.5 + Math.sin(tick * 0.07) * 0.22;
      const glow = ctx.createRadialGradient(centerX, centerY, 2, centerX, centerY, cellWidth * 0.62);
      glow.addColorStop(0, withAlpha(themeColors.accent, pulse));
      glow.addColorStop(1, withAlpha(themeColors.accent, 0));
      ctx.fillStyle = glow;
      ctx.fillRect(px - 6, py - 6, cellWidth + 12, cellHeight + 12);
      ctx.font = `${emojiSize * 0.6}px system-ui`;
      ctx.fillText("✨", centerX, centerY);
    }
    if (cell === "K") {
      const bounce = Math.sin(tick * 0.08 + x) * 3.5;
      const glow = ctx.createRadialGradient(centerX, centerY, 2, centerX, centerY, cellWidth * 0.55);
      glow.addColorStop(0, withAlpha(themeColors.accent, 0.4));
      glow.addColorStop(1, withAlpha(themeColors.accent, 0));
      ctx.fillStyle = glow;
      ctx.fillRect(px - 6, py - 6, cellWidth + 12, cellHeight + 12);
      ctx.font = `${emojiSize * 0.58}px system-ui`;
      ctx.fillText("🗝️", centerX, centerY + bounce);
    }
    if (cell === "*") {
      const bounce = Math.sin(tick * 0.09 + x * 2) * 2.5;
      ctx.font = `${emojiSize * 0.44}px system-ui`;
      ctx.fillText(gemEmoji, centerX, centerY + bounce);
    }
    if (cell === "D") {
      ctx.fillStyle = withAlpha(themeColors.background, 0.4);
      roundRect(px + 4, py + 4, cellWidth - 8, cellHeight - 8, 7);
      ctx.fill();
      ctx.font = `${emojiSize * 0.6}px system-ui`;
      ctx.fillText("🚪", centerX, centerY);
      if (keys === 0) {
        ctx.font = `${emojiSize * 0.3}px system-ui`;
        ctx.fillText("🔒", px + cellWidth - 12, py + 12);
      }
    }
  }));

  for (const ghost of ghosts) {
    const gx = ghost.fx * cellWidth + cellWidth / 2;
    const gy = ghost.y * cellHeight + cellHeight / 2 + Math.sin(tick * 0.1 + ghost.fx) * 3;
    const glow = ctx.createRadialGradient(gx, gy, 2, gx, gy, cellWidth * 0.55);
    glow.addColorStop(0, withAlpha(themeColors.text, 0.25));
    glow.addColorStop(1, withAlpha(themeColors.text, 0));
    ctx.fillStyle = glow;
    ctx.fillRect(gx - cellWidth * 0.6, gy - cellHeight * 0.6, cellWidth * 1.2, cellHeight * 1.2);
    ctx.save();
    if (ghost.dir < 0) {
      ctx.translate(gx, 0);
      ctx.scale(-1, 1);
      ctx.translate(-gx, 0);
    }
    ctx.font = `${emojiSize * 0.6}px system-ui`;
    ctx.fillText(ghostEmoji, gx, gy);
    ctx.restore();
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vx *= 0.96;
    p.vy *= 0.96;
    p.life -= 0.03;
    if (p.life <= 0) { particles.splice(i, 1); continue; }
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  drawn.x += (player.x - drawn.x) * 0.3;
  drawn.y += (player.y - drawn.y) * 0.3;
  bump.x *= 0.8;
  bump.y *= 0.8;
  const bob = Math.sin(tick * 0.12) * 2;
  const centerX = (drawn.x + bump.x) * cellWidth + cellWidth / 2;
  const centerY = (drawn.y + bump.y) * cellHeight + cellHeight / 2;
  const glow = ctx.createRadialGradient(centerX, centerY, 2, centerX, centerY, cellWidth * 0.6);
  glow.addColorStop(0, withAlpha(themeColors.surface, 0.32));
  glow.addColorStop(1, withAlpha(themeColors.surface, 0));
  ctx.fillStyle = glow;
  ctx.fillRect(centerX - cellWidth * 0.7, centerY - cellHeight * 0.7, cellWidth * 1.4, cellHeight * 1.4);
  ctx.font = `${emojiSize * 0.66}px system-ui`;
  ctx.fillText(explorerEmoji, centerX, centerY + bob);

  if (hurtFlash > 0.04) {
    ctx.fillStyle = `rgba(220, 38, 38, ${hurtFlash * 0.3})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  if (mode === "menu") {
    drawCard(`${explorerEmoji} Maze Explorer`, `Find 🗝️ and ${gemEmoji} · dodge ${ghostEmoji} · reach ✨`, "Tap, click, or press Enter to explore");
    status.textContent = "Ready?";
  }
  if (mode === "over") {
    drawCard(`${ghostEmoji} Game over!`, `${gemEmoji} Score ${score}`, "Tap, click, or press Enter to try again");
    status.textContent = `${gemEmoji} Score ${score}`;
  }
  if (mode === "won") {
    drawCard("🏆 Every maze explored!", `${gemEmoji} Final score ${score}`, "Tap, click, or press Enter to play again");
    status.textContent = `🏆 Score ${score}`;
  }
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

loadLevel();

function drawLoop() {
  draw();
  requestAnimationFrame(drawLoop);
}

drawLoop();

