// ⭐ CHANGE THESE
const pairs = ["🐶", "🐱", "🦊", "🐼", "🐸", "🦄"];
const matchMessage = "Matched!";

const board = document.getElementById("board");
const movesLabel = document.getElementById("moves");
const shuffleButton = document.getElementById("shuffle");
const win = document.getElementById("win");
const winMessage = document.getElementById("win-message");
const celebration = document.getElementById("celebration");
const playAgainButton = document.getElementById("play-again");
let cards = [];
let firstCard = null;
let lock = false;
let moves = 0;
let bestMoves = null;

shuffleButton.addEventListener("click", setup);
playAgainButton.addEventListener("click", setup);

function setup() {
  cards = [...pairs, ...pairs]
    .map((emoji, index) => ({ emoji, id: `${emoji}-${index}`, flipped: false, matched: false }))
    .sort(() => Math.random() - 0.5);
  firstCard = null;
  lock = false;
  moves = 0;
  win.hidden = true;
  celebration.innerHTML = "";
  buildBoard();
  updateLabel();
}

function buildBoard() {
  board.innerHTML = "";
  cards.forEach((card, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "card";
    button.setAttribute("aria-label", "Hidden card");
    button.style.animationDelay = `${index * 40}ms`;

    const inner = document.createElement("span");
    inner.className = "card-inner";
    const back = document.createElement("span");
    back.className = "card-back";
    back.textContent = "?";
    const front = document.createElement("span");
    front.className = "card-front";
    front.textContent = card.emoji;
    inner.append(back, front);
    button.append(inner);

    card.el = button;
    button.addEventListener("click", () => chooseCard(card));
    board.append(button);
  });
}

function reveal(card, shown) {
  card.flipped = shown;
  card.el.classList.toggle("flipped", shown || card.matched);
  card.el.setAttribute("aria-label", shown || card.matched ? card.emoji : "Hidden card");
}

function chooseCard(card) {
  if (lock || card.flipped || card.matched) return;
  reveal(card, true);
  if (!firstCard) {
    firstCard = card;
    return;
  }
  moves += 1;
  const first = firstCard;
  firstCard = null;
  if (first.emoji === card.emoji) {
    first.matched = true;
    card.matched = true;
    first.el.classList.add("matched");
    card.el.classList.add("matched");
    updateLabel();
    if (cards.every((item) => item.matched)) setTimeout(celebrateWin, 550);
    return;
  }
  lock = true;
  updateLabel();
  first.el.classList.add("wrong");
  card.el.classList.add("wrong");
  setTimeout(() => {
    first.el.classList.remove("wrong");
    card.el.classList.remove("wrong");
    reveal(first, false);
    reveal(card, false);
    lock = false;
  }, 780);
}

function updateLabel() {
  const found = cards.filter((card) => card.matched).length / 2;
  const best = bestMoves === null ? "" : ` · Best ${bestMoves}`;
  movesLabel.textContent = `Moves ${moves} · Pairs ${found}/${pairs.length}${best}`;
}

function celebrateWin() {
  bestMoves = bestMoves === null ? moves : Math.min(bestMoves, moves);
  winMessage.textContent = `${matchMessage} You found every pair in ${moves} moves. Best: ${bestMoves}.`;
  const pieces = ["✨", "⭐", "🎉", "💫"];
  for (let index = 0; index < 28; index += 1) {
    const piece = document.createElement("i");
    piece.textContent = pieces[index % pieces.length];
    piece.style.left = `${(index * 37) % 100}%`;
    piece.style.animationDelay = `${(index % 7) * -0.2}s`;
    piece.style.fontSize = `${22 + (index % 3) * 8}px`;
    celebration.append(piece);
  }
  win.hidden = false;
  playAgainButton.focus();
}

setup();

