/* jr-theme-tokens-v1 */
:root {
  --jr-bg: #0f766e;
  --jr-surface: #ecfeff;
  --jr-text: #f8fafc;
  --jr-accent: #facc15;
  --jr-accent-contrast: #172033;
}
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 22px 0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--jr-bg);
  color: var(--jr-text);
  position: relative;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(44vw 44vw at 10% 6%, rgba(255, 255, 255, 0.14), transparent 60%),
    radial-gradient(50vw 50vw at 92% 94%, rgba(0, 0, 0, 0.28), transparent 65%);
}
main { width: min(94vw, 780px); position: relative; }
header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}
p { margin: 0 0 5px; color: var(--jr-accent); font-weight: 900; text-transform: uppercase; letter-spacing: 0.08em; }
h1 {
  margin: 0;
  font-size: clamp(34px, 7vw, 62px);
  line-height: 0.95;
  text-shadow: 0 3px 0 rgba(0, 0, 0, 0.18), 0 12px 28px rgba(0, 0, 0, 0.3);
}
strong {
  border: 2px solid var(--jr-accent);
  border-radius: 999px;
  padding: 9px 14px;
  background: var(--jr-accent);
  color: var(--jr-accent-contrast);
  white-space: nowrap;
}
.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  perspective: 1100px;
}
.card {
  aspect-ratio: 1;
  border: 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
  animation: deal 0.45s both;
}
.card-inner {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 0.45s cubic-bezier(0.34, 1.3, 0.5, 1);
}
.card.flipped .card-inner { transform: rotateY(180deg); }
.card:not(.flipped):hover .card-inner { transform: rotateY(0deg) translateY(-4px); }
.card-back,
.card-front {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 14px;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  font-size: clamp(34px, 8vw, 58px);
  font-weight: 900;
}
.card-back {
  background:
    repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.14) 0 10px, transparent 10px 20px),
    linear-gradient(160deg, color-mix(in srgb, var(--jr-accent) 80%, white), var(--jr-accent) 45%, color-mix(in srgb, var(--jr-accent) 72%, black));
  color: var(--jr-accent-contrast);
  box-shadow: 0 6px 0 color-mix(in srgb, var(--jr-accent) 55%, black), 0 14px 26px rgba(0, 0, 0, 0.22);
  text-shadow: 0 2px 0 rgba(255, 255, 255, 0.3);
}
.card-front {
  background: linear-gradient(180deg, white, var(--jr-surface));
  color: #134e4a;
  transform: rotateY(180deg);
  box-shadow: 0 6px 0 rgba(0, 0, 0, 0.14), 0 14px 26px rgba(0, 0, 0, 0.2), inset 0 0 0 3px rgba(19, 78, 74, 0.1);
}
.card.matched { animation: match-pop 0.5s ease; cursor: default; }
.card.matched .card-front {
  box-shadow: 0 0 0 4px var(--jr-accent), 0 0 22px color-mix(in srgb, var(--jr-accent) 75%, transparent), 0 6px 0 rgba(0, 0, 0, 0.14);
}
.card.wrong { animation: shake 0.4s ease; }
.card.wrong .card-front {
  box-shadow: 0 0 0 4px #ef4444, 0 6px 0 rgba(0, 0, 0, 0.14), 0 14px 26px rgba(0, 0, 0, 0.2);
}
#shuffle {
  width: 100%;
  height: 48px;
  margin-top: 16px;
  border: 0;
  border-radius: 12px;
  background: var(--jr-accent);
  color: var(--jr-accent-contrast);
  font-weight: 900;
  font-size: 16px;
  cursor: pointer;
  box-shadow: 0 5px 0 color-mix(in srgb, var(--jr-accent) 55%, black);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
#shuffle:hover { transform: translateY(-2px); }
#shuffle:active { transform: translateY(3px); box-shadow: 0 1px 0 color-mix(in srgb, var(--jr-accent) 55%, black); }
.win {
  position: fixed;
  inset: 0;
  z-index: 5;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 12px;
  padding: 24px;
  background: color-mix(in srgb, var(--jr-bg) 88%, black);
  text-align: center;
  animation: win-in 0.4s ease both;
}
.win[hidden] { display: none; }
.win > span { font-size: 88px; animation: trophy 0.8s ease-in-out infinite alternate; filter: drop-shadow(0 10px 22px rgba(0, 0, 0, 0.4)); }
.win h2 { margin: 0; font-size: clamp(38px, 8vw, 72px); text-shadow: 0 4px 0 rgba(0, 0, 0, 0.2); }
.win p { margin: 0; color: var(--jr-accent); font-size: 22px; font-weight: 900; }
.win button {
  width: min(320px, 80vw);
  height: 50px;
  border: 0;
  border-radius: 12px;
  font-weight: 900;
  font-size: 16px;
  cursor: pointer;
  background: var(--jr-accent);
  color: var(--jr-accent-contrast);
  box-shadow: 0 5px 0 color-mix(in srgb, var(--jr-accent) 55%, black);
}
.win button:active { transform: translateY(3px); box-shadow: 0 1px 0 color-mix(in srgb, var(--jr-accent) 55%, black); }
.celebration { position: fixed; inset: 0; pointer-events: none; overflow: hidden; }
.celebration i {
  position: absolute;
  top: -40px;
  font-style: normal;
  font-size: 28px;
  animation: confetti-fall 2.2s linear infinite;
}
@keyframes deal { from { opacity: 0; transform: translateY(20px) scale(0.9) rotate(-3deg); } }
@keyframes win-in { from { opacity: 0; transform: scale(0.96); } }
@keyframes trophy { to { transform: translateY(-10px) rotate(5deg) scale(1.08); } }
@keyframes confetti-fall { to { transform: translateY(115vh) rotate(540deg); } }
@keyframes match-pop { 45% { transform: scale(1.09); } }
@keyframes shake {
  20% { transform: translateX(-7px); }
  45% { transform: translateX(6px); }
  70% { transform: translateX(-4px); }
  90% { transform: translateX(2px); }
}

// ⭐ CHANGE THESE
const questions = [
  {
    q: "Which planet is known as the red planet?",
    answers: ["Mars", "Venus", "Earth", "Neptune"],
    correct: "Mars"
  },
  {
    q: "What do bees make?",
    answers: ["Honey", "Clouds", "Pizza", "Bricks"],
    correct: "Honey"
  },
  {
    q: "How many sides does a triangle have?",
    answers: ["2", "3", "4", "5"],
    correct: "3"
  },
  {
    q: "Which animal says ribbit?",
    answers: ["Frog", "Horse", "Penguin", "Koala"],
    correct: "Frog"
  }
];
const confettiColors = ["#fde68a", "#4ade80", "#38bdf8", "#f472b6", "#fb923c"];

let index = 0;
let score = 0;
let streak = 0;
const question = document.getElementById("question");
const answers = document.getElementById("answers");
const feedback = document.getElementById("feedback");
const progress = document.getElementById("progress");
const status = document.getElementById("status");
const letters = ["A", "B", "C", "D", "E", "F"];

function renderQuestion() {
  const current = questions[index];
  question.textContent = current.q;
  answers.innerHTML = "";
  status.textContent = `Question ${index + 1} · Score ${score} · Streak ${streak}${streak > 1 ? " 🔥" : ""}`;
  progress.style.width = `${(index / questions.length) * 100}%`;
  current.answers.forEach((answer, i) => {
    const button = document.createElement("button");
    button.type = "button";
    const letter = document.createElement("span");
    letter.className = "letter";
    letter.textContent = letters[i % letters.length];
    const label = document.createElement("span");
    label.textContent = answer;
    button.append(letter, label);
    button.dataset.answer = answer;
    button.addEventListener("click", () => choose(answer, button));
    answers.append(button);
  });
}

function choose(answer, chosen) {
  const current = questions[index];
  const correct = answer === current.correct;
  for (const button of answers.querySelectorAll("button")) {
    button.disabled = true;
    const isRight = button.dataset.answer === current.correct;
    if (isRight) button.classList.add("correct");
    else if (button === chosen) button.classList.add("wrong");
    else button.classList.add("faded");
  }
  if (correct) {
    score += 10 + streak * 2;
    streak += 1;
    feedback.textContent = streak > 2 ? `Correct! ${streak} in a row! 🔥` : "Correct! Keep the streak going. ✨";
  } else {
    streak = 0;
    feedback.textContent = `Close! The answer was ${current.correct}.`;
  }
  index += 1;
  if (index >= questions.length) {
    setTimeout(showResult, 1000);
    return;
  }
  setTimeout(renderQuestion, 1000);
}

function throwConfetti() {
  for (let i = 0; i < 90; i++) {
    const piece = document.createElement("span");
    piece.className = "confetti";
    piece.style.left = `${Math.random() * 100}vw`;
    piece.style.background = confettiColors[i % confettiColors.length];
    piece.style.animationDuration = `${2.2 + Math.random() * 2.4}s`;
    piece.style.animationDelay = `${Math.random() * 0.9}s`;
    piece.style.transform = `rotate(${Math.random() * 360}deg) scale(${0.6 + Math.random() * 0.8})`;
    document.body.append(piece);
    setTimeout(() => piece.remove(), 6000);
  }
}

function showResult() {
  progress.style.width = "100%";
  status.textContent = "Final score";
  question.textContent = `🏆 ${score} points`;
  feedback.textContent = "You finished the show.";
  answers.innerHTML = "";
  throwConfetti();
  const replay = document.createElement("button");
  replay.type = "button";
  const letter = document.createElement("span");
  letter.className = "letter";
  letter.textContent = "↻";
  const label = document.createElement("span");
  label.textContent = "Play again";
  replay.append(letter, label);
  replay.addEventListener("click", () => {
    index = 0;
    score = 0;
    streak = 0;
    feedback.textContent = "Build a streak.";
    renderQuestion();
  });
  answers.append(replay);
}

renderQuestion();

