:root {
  --jr-bg: #4c1d95;
  --jr-surface: #f8fafc;
  --jr-text: #172033;
  --jr-accent: #0f766e;
  --jr-accent-contrast: #ffffff;
}
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--jr-bg);
  color: #f8fafc;
  position: relative;
  overflow-x: hidden;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(46vw 46vw at 12% 8%, rgba(255, 255, 255, 0.16), transparent 60%),
    radial-gradient(52vw 52vw at 88% 92%, rgba(0, 0, 0, 0.3), transparent 65%),
    radial-gradient(34vw 34vw at 82% 12%, rgba(253, 230, 138, 0.2), transparent 60%);
}
body::after {
  content: "";
  position: fixed;
  inset: -60vmax;
  pointer-events: none;
  background: conic-gradient(
    rgba(255, 255, 255, 0.07) 0deg 14deg, transparent 14deg 52deg,
    rgba(255, 255, 255, 0.07) 52deg 66deg, transparent 66deg 118deg,
    rgba(255, 255, 255, 0.07) 118deg 132deg, transparent 132deg 360deg
  );
  animation: rays 60s linear infinite;
}
@keyframes rays { to { transform: rotate(360deg); } }
.quiz-shell { width: min(94vw, 820px); position: relative; z-index: 1; padding: 26px 0; }
