button:nth-child(2) { animation-delay: 0.06s; }
button:nth-child(3) { animation-delay: 0.12s; }
button:nth-child(4) { animation-delay: 0.18s; }
button:hover { transform: translateY(-2px); filter: brightness(1.08); }
button:active { transform: translateY(3px); box-shadow: 0 2px 0 color-mix(in srgb, var(--jr-accent) 55%, black), 0 6px 12px rgba(0, 0, 0, 0.18); }
