const recipes = [
  {
    name: "Rainbow Tacos",
    emoji: "🌮",
    time: "20 minutes",
    ingredients: ["Tortillas", "Beans", "Corn", "Tomatoes", "Cheese"],
    steps: ["Warm the tortillas.", "Fill with colorful toppings.", "Fold and enjoy."]
  },
  {
    name: "Cozy Soup",
    emoji: "🍲",
    time: "35 minutes",
    ingredients: ["Carrots", "Noodles", "Vegetable broth", "Peas"],
    steps: ["Simmer the vegetables.", "Add noodles.", "Serve warm in big bowls."]
  },
  {
    name: "Berry Toast",
    emoji: "🍓",
    time: "10 minutes",
    ingredients: ["Toast", "Cream cheese", "Strawberries", "Honey"],
    steps: ["Spread cream cheese.", "Add berries.", "Drizzle honey on top."]
  }
];

const recipesEl = document.getElementById("recipes");
const detail = document.getElementById("detail");
let selected = 0;

function renderCards() {
  recipesEl.innerHTML = "";
  recipes.forEach((recipe, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = index === selected ? "recipe-card selected" : "recipe-card";
    button.style.animationDelay = `${index * 90}ms`;
    button.innerHTML = `<span>${recipe.emoji}</span><div><h2>${recipe.name}</h2><p>${recipe.time}</p></div>`;
    button.addEventListener("click", () => {
      selected = index;
      render();
    });
    recipesEl.append(button);
  });
}

function renderDetail() {
  const recipe = recipes[selected];
  detail.innerHTML = `
    <h2>${recipe.emoji} ${recipe.name}</h2>
    <p class="meta">${recipe.time}</p>
    <div class="columns">
      <div>
        <h3>Ingredients</h3>
        ${recipe.ingredients.map((item) => `<label><input type="checkbox" /> ${item}</label>`).join("")}
      </div>
      <div>
        <h3>Steps</h3>
        <ol>${recipe.steps.map((step) => `<li>${step}</li>`).join("")}</ol>
      </div>
    </div>
  `;
}

function render() {
  renderCards();
  renderDetail();
}

render();

