window.addEventListener("keyup", (event) => keys.delete(event.key));
canvas.addEventListener("pointermove", (event) => {
  const rect = canvas.getBoundingClientRect();
  ship.x = ((event.clientX - rect.left) / rect.width) * canvas.width;
  ship.y = ((event.clientY - rect.top) / rect.height) * canvas.height;
});
canvas.addEventListener("pointerdown", () => {
  if (mode === "playing") fireLaser();
  else startGame();
});

function startGame() {
  lasers.length = 0;
  enemies.length = 0;
  sparks.length = 0;
  drops.length = 0;
  score = 0;
  lives = 3;
  wave = 0;
  tick = 0;
  rapidUntil = 0;
  shield = false;
  mode = "playing";
  nextWave();
}

function nextWave() {
  wave += 1;
  waveBanner = 90;
  for (let i = 0; i < 5 + wave; i++) {
    const zig = wave > 1 && Math.random() < 0.3;
    enemies.push({
      x: 90 + (i % 7) * 110,
      y: -60 - Math.floor(i / 7) * 70,
      vx: i % 2 === 0 ? 1.2 : -1.2,
      vy: (zig ? 1.7 : 1.2) + wave * 0.15,
      kind: Math.random() < 0.75 ? "alien" : "meteor",
      zig,
      phase: Math.random() * Math.PI * 2,
      spin: Math.random() * Math.PI * 2
    });
  }
}

function fireLaser() {
  lasers.push({ x: ship.x, y: ship.y - 38, vy: -10 });
}

function explode(x, y, count) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const force = 1.5 + Math.random() * 3;
    sparks.push({ x, y, vx: Math.cos(angle) * force, vy: Math.sin(angle) * force, life: 22 });
  }
}

function hitShip() {
  if (shield) {
    shield = false;
    explode(ship.x, ship.y - 20, 12);
    return;
  }
  lives -= 1;
  shake = 14;
  explode(ship.x, ship.y - 20, 20);
  if (lives <= 0) {
    bestScore = Math.max(bestScore, score);
    mode = "over";
  }
}

function catchPowerup(drop) {
  if (drop.type === "rapid") rapidUntil = tick + 480;
  if (drop.type === "shield") shield = true;
  explode(drop.x, drop.y, 8);
}

function update() {
  tick += 1;
  shake *= 0.85;
  if (waveBanner > 0) waveBanner -= 1;
  if (mode !== "playing") return;

  if (keys.has("ArrowLeft")) ship.x -= ship.speed;
  if (keys.has("ArrowRight")) ship.x += ship.speed;
  if (keys.has("ArrowUp")) ship.y -= ship.speed;
  if (keys.has("ArrowDown")) ship.y += ship.speed;
  ship.x = Math.max(30, Math.min(canvas.width - 30, ship.x));
  ship.y = Math.max(90, Math.min(canvas.height - 34, ship.y));
  if (tick % (tick < rapidUntil ? 6 : 16) === 0) fireLaser();
  if (enemies.length === 0) nextWave();

  for (const laser of lasers) laser.y += laser.vy;
  for (const enemy of enemies) {
    enemy.x += enemy.vx + (enemy.zig ? Math.sin(tick * 0.06 + enemy.phase) * 2.2 : 0);
    enemy.y += enemy.vy;
    enemy.spin += enemy.kind === "meteor" ? 0.012 : 0;
    if (enemy.x < 40 || enemy.x > canvas.width - 40) enemy.vx *= -1;
  }

  for (const laser of lasers) {
    for (const enemy of enemies) {
      if (enemy.hit) continue;
      if (Math.abs(laser.x - enemy.x) < 32 && Math.abs(laser.y - enemy.y) < 34) {
        enemy.hit = true;
        laser.done = true;
        score += enemy.zig ? 20 : 10;
        explode(enemy.x, enemy.y, 8);
        if (Math.random() < 0.14) {
          const powerup = powerups[Math.floor(Math.random() * powerups.length)];
          drops.push({ ...powerup, x: enemy.x, y: enemy.y, vy: 2.4 });
        }
      }
    }
  }

  for (const enemy of enemies) {
    if (enemy.hit) continue;
    if (Math.abs(enemy.x - ship.x) < 40 && Math.abs(enemy.y - (ship.y - 20)) < 42) {
      enemy.hit = true;
      explode(enemy.x, enemy.y, 10);
      hitShip();
    } else if (enemy.y > canvas.height + 60) {
      enemy.hit = true;
    }
  }

  for (let i = drops.length - 1; i >= 0; i--) {
    const drop = drops[i];
    drop.y += drop.vy;
    if (Math.abs(drop.x - ship.x) < 42 && Math.abs(drop.y - (ship.y - 20)) < 44) {
      catchPowerup(drop);
      drops.splice(i, 1);
    } else if (drop.y > canvas.height + 30) {
      drops.splice(i, 1);
    }
  }

  for (let i = lasers.length - 1; i >= 0; i--) {
    if (lasers[i].done || lasers[i].y < -20) lasers.splice(i, 1);
  }
  for (let i = enemies.length - 1; i >= 0; i--) {
    if (enemies[i].hit) enemies.splice(i, 1);
  }
  for (const spark of sparks) {
    spark.x += spark.vx;
    spark.y += spark.vy;
    spark.life -= 1;
  }
  for (let i = sparks.length - 1; i >= 0; i--) {
    if (sparks[i].life <= 0) sparks.splice(i, 1);
  }
  bestScore = Math.max(bestScore, score);
  hud.textContent = `Wave ${wave} · Score ${score} · ${"❤️".repeat(Math.max(0, lives))}${shield ? " · 🛡️" : ""}${tick < rapidUntil ? " · ⚡" : ""}`;
}

function drawCard(title, line1, line2) {
  ctx.save();
  ctx.globalAlpha = 0.55;
  ctx.fillStyle = themeColors.background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.restore();
  ctx.fillStyle = themeColors.surface;
  ctx.beginPath();
  ctx.roundRect(canvas.width / 2 - 230, 160, 460, 230, 22);
  ctx.fill();
  ctx.fillStyle = themeColors.text;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "44px system-ui";
  ctx.fillText(title, canvas.width / 2, 225);
  ctx.font = "23px system-ui";
  ctx.fillText(line1, canvas.width / 2, 285);
  ctx.font = "19px system-ui";
  ctx.fillText(line2, canvas.width / 2, 340);
}

function draw() {
  ctx.save();
  if (shake > 0.5) {
    ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
  }
  drawSpace();
  ctx.fillStyle = themeColors.text;
  for (let i = 0; i < 120; i++) {
    const starSize = i % 11 === 0 ? 2.4 : 1.2;
    ctx.globalAlpha = 0.25 + ((i * 17 + tick) % 50) / 100;
    ctx.fillRect(
      (i * 89) % canvas.width,
      (i * 47 + tick * (i % 3 === 0 ? 0.7 : 0.28)) % canvas.height,
      starSize,
      starSize
    );
  }
  ctx.globalAlpha = 1;

  ctx.save();
  ctx.shadowColor = themeColors.laser;
  ctx.shadowBlur = 18;
  for (const laser of lasers) {
    const beam = ctx.createLinearGradient(laser.x, laser.y - 28, laser.x, laser.y + 6);
    beam.addColorStop(0, "rgba(255, 255, 255, 0)");
    beam.addColorStop(0.35, "#ffffff");
    beam.addColorStop(1, themeColors.laser);
    ctx.fillStyle = beam;
    ctx.fillRect(laser.x - 3, laser.y - 28, 6, 34);
  }
  ctx.restore();

  for (const enemy of enemies) {
    const image = artwork[enemy.kind];
    const size = enemy.kind === "meteor" ? 68 : 76;
    ctx.save();
    ctx.translate(enemy.x, enemy.y - 12);
    ctx.rotate(enemy.spin);
    if (enemy.zig) {
      ctx.shadowColor = themeColors.laser;
      ctx.shadowBlur = 16;
    }
    drawSprite(image, enemy.kind === "meteor" ? "☄️" : "👾", size);
    ctx.restore();
  }

  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  for (const drop of drops) {
    ctx.font = "32px system-ui";
    ctx.fillText(drop.emoji, drop.x, drop.y + Math.sin(tick * 0.15) * 3);
  }

  if (shield) {
    ctx.strokeStyle = themeColors.laser;
    ctx.globalAlpha = 0.55 + Math.sin(tick * 0.15) * 0.2;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(ship.x, ship.y - 20, 54, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  ctx.save();
  ctx.translate(ship.x, ship.y - 20);
  ctx.shadowColor = "rgba(72, 216, 255, 0.75)";
  ctx.shadowBlur = 18;
  drawSprite(artwork.ship, "🚀", 96);
  ctx.restore();

  ctx.fillStyle = themeColors.laser;
  for (const spark of sparks) {
    ctx.globalAlpha = spark.life / 22;
    ctx.fillRect(spark.x, spark.y, 5, 5);
  }
  ctx.globalAlpha = 1;

  if (mode === "playing" && waveBanner > 0) {
    ctx.globalAlpha = Math.min(1, waveBanner / 30);
    ctx.fillStyle = themeColors.text;
    ctx.font = "bold 40px system-ui";
    ctx.fillText(`Wave ${wave}`, canvas.width / 2, 150);
    ctx.globalAlpha = 1;
  }

  if (mode === "menu") {
    drawCard("🚀 Space Shooter", "Blast 👾 and ☄️ · catch ⚡ 🛡️ powerups!", "Tap, click, or press Space to launch");
    hud.textContent = "Ready?";
  }
  if (mode === "over") {
    drawCard("💥 Game over!", `Score ${score} · Best ${bestScore}`, "Tap, click, or press Space to fly again");
    hud.textContent = `Score ${score} · Best ${bestScore}`;
  }
  ctx.restore();
}

function drawSpace() {
  ctx.fillStyle = themeColors.surface;
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  if (artwork.background.complete && artwork.background.naturalWidth > 0) {
    ctx.drawImage(artwork.background, 0, 0, canvas.width, canvas.height);
    const tint = ctx.createLinearGradient(0, 0, 0, canvas.height);
    tint.addColorStop(0, "rgba(2, 6, 23, 0.08)");
    tint.addColorStop(0.55, "rgba(2, 6, 23, 0.18)");
    tint.addColorStop(1, "rgba(2, 6, 23, 0.5)");
    ctx.fillStyle = tint;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    return;
  }
  const nebula1 = ctx.createRadialGradient(220, 160, 20, 220, 160, 260);
  nebula1.addColorStop(0, "rgba(129, 140, 248, 0.16)");
  nebula1.addColorStop(1, "rgba(129, 140, 248, 0)");
  ctx.fillStyle = nebula1;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const nebula2 = ctx.createRadialGradient(700, 420, 20, 700, 420, 300);
  nebula2.addColorStop(0, "rgba(244, 114, 182, 0.12)");
  nebula2.addColorStop(1, "rgba(244, 114, 182, 0)");
  ctx.fillStyle = nebula2;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function drawSprite(image, fallback, size) {
  if (image.complete && image.naturalWidth > 0) {
    ctx.drawImage(image, -size / 2, -size / 2, size, size);
    return;
  }
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = `${Math.round(size * 0.62)}px system-ui`;
  ctx.fillText(fallback, 0, 0);
}

function loadImage(source) {
  const image = new Image();
  image.src = source;
  return image;
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

