// ⭐ CHANGE THESE
const scenes = [
  { name: "Sunny park", sky: "#7dd3fc", ground: "#86efac" },
  { name: "Sunset", sky: "#fda4af", ground: "#fdba74" },
  { name: "Moonlight", sky: "#312e81", ground: "#155e75" }
];
const startingStickers = [
  { emoji: "🦄", label: "Dream big", x: 20, y: 55, rotation: -5 },
  { emoji: "🌈", label: "Good vibes", x: 52, y: 18, rotation: 4 },
  { emoji: "🏰", label: "Adventure", x: 72, y: 52, rotation: 2 },
  { emoji: "🦋", label: "Hello!", x: 38, y: 40, rotation: -8 }
];
const extraStickers = ["🚀", "🐱", "🌻", "🐉", "🎸", "🍕"];

const scene = document.getElementById("scene");
const backgrounds = document.getElementById("backgrounds");
const message = document.getElementById("message");
const addButton = document.getElementById("add");
const removeButton = document.getElementById("remove");
const resetButton = document.getElementById("reset");
let stickers = [];
let selectedId = null;
let drag = null;
let extraIndex = 0;
let nextId = 1;

scenes.forEach((item, index) => {
  const button = document.createElement("button");
  button.type = "button";
  button.textContent = item.name;
  button.addEventListener("click", () => applyScene(index));
  backgrounds.append(button);
});
addButton.addEventListener("click", addSticker);
removeButton.addEventListener("click", removeSelected);
resetButton.addEventListener("click", reset);
window.addEventListener("pointermove", moveDrag);
window.addEventListener("pointerup", endDrag);

function reset() {
  stickers = startingStickers.map((sticker) => ({ ...sticker, id: nextId++ }));
  selectedId = stickers[0].id;
  extraIndex = 0;
  applyScene(0);
  render();
  message.textContent = "Pick up any sticker!";
}

function applyScene(index) {
  const item = scenes[index];
  scene.style.background = `linear-gradient(${item.sky} 0 66%, ${item.ground} 66%)`;
  [...backgrounds.children].forEach((button, buttonIndex) => button.classList.toggle("selected", buttonIndex === index));
  message.textContent = `${item.name} background selected.`;
}

function addSticker() {
  const emoji = extraStickers[extraIndex % extraStickers.length];
  extraIndex += 1;
  const sticker = { id: nextId++, emoji, label: "New sticker", x: 50, y: 48, rotation: (extraIndex % 3 - 1) * 6 };
  stickers.push(sticker);
  selectedId = sticker.id;
  render();
  scene.querySelector(`[data-id="${sticker.id}"]`)?.focus();
  message.textContent = `${emoji} added. Drag it into place.`;
}

function removeSelected() {
  if (selectedId === null) return;
  stickers = stickers.filter((sticker) => sticker.id !== selectedId);
  selectedId = stickers[0]?.id ?? null;
  render();
  message.textContent = "Sticker removed.";
}

function selectSticker(id) {
  selectedId = id;
  scene.querySelectorAll(".sticker").forEach((element) => {
    element.classList.toggle("selected", Number(element.dataset.id) === id);
  });
}

function startDrag(event, id) {
  selectSticker(id);
  drag = { id };
  moveDrag(event);
}

function moveDrag(event) {
  if (!drag) return;
  const rect = scene.getBoundingClientRect();
  const sticker = stickers.find((item) => item.id === drag.id);
  if (!sticker) return;
  sticker.x = clamp(((event.clientX - rect.left) / rect.width) * 100, 5, 90);
  sticker.y = clamp(((event.clientY - rect.top) / rect.height) * 100, 6, 82);
  positionElement(sticker);
}

function endDrag() {
  if (!drag) return;
  message.textContent = "Nice placement! Use arrow keys for tiny moves.";
  drag = null;
}

function nudge(event, sticker) {
  const movement = { ArrowLeft: [-2, 0], ArrowRight: [2, 0], ArrowUp: [0, -2], ArrowDown: [0, 2] }[event.key];
  if (!movement) return;
  event.preventDefault();
  sticker.x = clamp(sticker.x + movement[0], 5, 90);
  sticker.y = clamp(sticker.y + movement[1], 6, 82);
  positionElement(sticker);
}

function render() {
  scene.querySelectorAll(".sticker").forEach((element) => element.remove());
  stickers.forEach((sticker, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = sticker.id === selectedId ? "sticker selected" : "sticker";
    button.dataset.id = String(sticker.id);
    button.setAttribute("aria-label", `${sticker.label}, ${sticker.emoji}. Drag or use arrow keys to move.`);
    button.style.animationDelay = `${index * 80}ms`;
    const emoji = document.createElement("span");
    emoji.className = "emoji";
    emoji.textContent = sticker.emoji;
    const label = document.createElement("span");
    label.className = "label";
    label.textContent = sticker.label;
    button.append(emoji, label);
    button.addEventListener("focus", () => selectSticker(sticker.id));
    button.addEventListener("pointerdown", (event) => startDrag(event, sticker.id));
    button.addEventListener("keydown", (event) => nudge(event, sticker));
    scene.append(button);
    positionElement(sticker);
  });
}

function positionElement(sticker) {
  const element = scene.querySelector(`[data-id="${sticker.id}"]`);
  if (!element) return;
  element.style.left = `${sticker.x}%`;
  element.style.top = `${sticker.y}%`;
  element.style.transform = `translate(-50%, -50%) rotate(${sticker.rotation}deg)`;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

reset();

