.sticker .label { margin-top: 3px; border-radius: 999px; padding: 3px 8px; background: var(--jr-surface); color: var(--jr-text); font-size: 13px; font-weight: 900; box-shadow: 0 3px 8px rgba(15, 23, 42, 0.15); }
@keyframes sticker-pop { from { opacity: 0; transform: scale(0.4) rotate(-15deg); } }
@keyframes sticker-bob { 50% { transform: translateY(-6px) rotate(3deg); } }
@keyframes sun-pulse { 50% { transform: scale(1.1) rotate(8deg); } }
@keyframes cloud-drift { to { transform: translateX(80px); } }
@media (max-width: 680px) {
  header { align-items: start; flex-direction: column; }
  header strong { text-align: left; }
}
